-- ============================================================================
-- SC3 PROFESSIONAL DEEP SEED: Materials, Spares & Inventory Management, intermediate tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/materials/intermediate.
--
-- What this tier owns: SERVICE LEVELS, SAFETY STOCK AND DISCOUNTS. Quantity
-- discounts, all-units and incremental; demand over the lead time and sigma
-- over the protection period; the cycle service level and the safety factor;
-- the fill rate and the unit normal loss; periodic review and the
-- order-up-to level; Poisson demand for slow movers.
--
-- AN APP COURSE. The Suite app is the Materials & Spares Planner; the
-- practicals also run in the course's own stock calculator. The capstone
-- grades six values of this tier, each identical under every reading the
-- engine states and never a Monte Carlo draw.
-- ============================================================================

insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
values ('materials', 'intermediate', '{"modules":[{"key":"m01-quantity-discounts","title":"Quantity Discounts","lesson_keys":["l01-a-price-schedule","l02-all-units-discounts","l03-incremental-discounts","l04-candidates-and-the-lowest-total-cost","l05-rounding-against-the-breaks"]},{"key":"m02-demand-over-the-lead-time","title":"Demand over the Lead Time","lesson_keys":["l01-continuous-review-and-the-reorder-point","l02-demand-and-lead-time-variation","l03-sigma-over-the-protection-period","l04-the-choke-bean-set"]},{"key":"m03-the-cycle-service-level","title":"The Cycle Service Level","lesson_keys":["l01-the-probability-of-no-stockout","l02-the-safety-factor-from-the-inverse-normal","l03-a-safety-factor-read-from-a-table","l04-the-published-safety-stocks"]},{"key":"m04-the-fill-rate","title":"The Fill Rate","lesson_keys":["l01-units-short-per-cycle","l02-the-unit-normal-loss","l03-solving-for-the-safety-factor","l04-a-printed-figure-that-is-a-slip"]},{"key":"m05-periodic-review","title":"Periodic Review","lesson_keys":["l01-the-review-period","l02-the-order-up-to-level","l03-a-floor-on-the-safety-factor","l04-certain-demand"]},{"key":"m06-poisson-demand-for-slow-movers","title":"Poisson Demand for Slow Movers","lesson_keys":["l01-when-the-normal-does-not-fit","l02-the-poisson-table","l03-cycle-service-on-a-poisson","l04-fill-rate-and-the-loss-recursion","l05-the-capstone-brief"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
      updated_at = now();

delete from public.academy_quiz_questions
 where app_slug = 'materials' and tier = 'intermediate';

insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 1, 'The casing joint CSG-958 on the Ekene register states a demand of 240 a year, an order cost of 3500, a holding rate of 0.2, prices of 1450 from 0, 1400 from 60 and 1360 from 120, rounded to the nearest whole joint, with the discount type all-units. What does the engine order?', '["141.000000 joints in band 2, at 365590.042553 a year, pricing each joint by its own band", "77.000000 joints in band 1, at 357689.090909 a year", "120.000000 joints in band 2, at a total cost of 349720.000000 a year", "76.112440 joints, the no-discount baseline at the band 0 price"]'::jsonb, 2, 'Under all-units the band 2 EOQ of 78.590525 lies below its break, so the break quantity 120.000000 is the candidate, and at 349720.000000 it beats band 1''s 77.000000 at 357689.090909. The order of 141.000000 at 365590.042553 is the incremental reading of the same schedule, and 76.112440 is the baseline every saving is measured from.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 2, 'The same casing schedule is stated with the discount type incremental, every other input unchanged. What quantity does the engine order, and at what total cost a year?', '["141.000000 joints at 365590.042553 a year, band 2''s EOQ rounded to the nearest joint", "120.000000 joints at 349720.000000 a year, taking the break as all-units does", "106.000000 joints at 365856.981132 a year, the band 1 candidate", "141.213231 joints, the band 2 EOQ carried unrounded into the order"]'::jsonb, 0, 'Under incremental pricing band 2 offers its own EOQ, 141.213231, rounded by the stated rule to the nearest whole joint, 141.000000, at 365590.042553 a year, which is below band 1''s 106.000000 at 365856.981132. The break quantity 120.000000 is the all-units answer, and the unrounded EOQ is the figure before the stated rule acts.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 3, 'On the casing read as all-units, the engine''s reason for band 0 is quoted below. What does it say the band offers?

> band 0 at 1450: EOQ 76.11244 lies at or above the next break 60, so the band gives no candidate', '["The break quantity 60, costed at the band 0 price", "Its EOQ rounded to the nearest joint, in band 0", "A refusal of the schedule as a policy that cannot work", "No candidate, since a cheaper band covers that quantity"]'::jsonb, 3, 'Under all-units a band whose EOQ falls at or above the next break offers no candidate, because a cheaper band covers that quantity. The engine does not refuse the schedule: it goes on to band 1 and band 2 and orders 120.000000. A band whose EOQ falls below its own break is the case that offers the break quantity.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 4, 'Under all-units on the casing, band 2''s EOQ is 78.590525 and its break is 120. What does band 2 offer as its candidate?', '["Its EOQ 78.590525 rounded to the nearest joint, costed in band 1", "The break quantity, 120.000000, at 349720.000000 a year", "Nothing, because its EOQ lies outside the band", "The EOQ as it stands, costed at the band 2 price of 1360 a joint"]'::jsonb, 1, 'The engine''s reason for band 2 reads: band 2 at 1360: EOQ 78.590525 lies below the break 120, so the break quantity is the candidate, total cost 349720 a year. Ordering less than 120 would lose the price, so an all-units band whose EOQ falls below its break offers the break. Offering nothing is the rule for an EOQ at or above the NEXT break.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 5, 'Under the incremental reading of the casing schedule, what fixed cost F2 does the engine carry for band 2, the band that starts at 120?', '["3000.000000", "7500.000000", "7800.000000", "0.000000"]'::jsonb, 2, 'The engine''s basis states Fi = Fi-1 + (vi-1 - vi) Qi. Band 1 starts at 60 and costs 50 less than band 0, so F1 is 3000.000000; band 2 starts at 120 and costs 40 less than band 1, which lifts F2 to 7800.000000. The figure 7500.000000 belongs to the lecture 8 schedule priced from 50, and 0.000000 is the fixed cost of band 0 alone.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 6, 'What saving against the no-discount baseline does the engine report for the casing under each discount type?', '["4482.564905 all-units and 20352.607458 under incremental pricing", "20352.607458 under both types", "No saving under either type", "20352.607458 all-units and 4482.564905 incremental"]'::jsonb, 3, 'All-units orders 120.000000 at 349720.000000 a year, a saving of 20352.607458; incremental orders 141.000000 at 365590.042553, a saving of 4482.564905. Incremental gives the band 2 price only to the joints above 120, so the discount buys less. Both savings are measured from the EOQ 76.11244 at the band 0 price.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 7, 'Caplice, lecture 8 slide 12, states a two per cent all-units discount from 500 units on a demand of 2000 a year, an order cost of 500, a holding rate of 0.25 and a price of 50, and prints no answer. What does the engine order?', '["500.000000 at 103062.500000 a year", "400.000000 at 105000.000000 a year, the band 0 EOQ", "1000.000000 at 86000.000000", "1789.000000 at 98826.043879 a year, the incremental order"]'::jsonb, 0, 'The engine''s reason reads: order 500 at a total cost of 103062.5 a year (band 1), the lowest of 2 candidates. Against 105000.000000 at the band 0 EOQ of 400.000000, the break is worth taking. The orders of 1000.000000 and 1789.000000 belong to the three-band schedule of slides 13 to 15, read as all-units and as incremental.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 8, 'Caplice, lecture 8 slides 13 to 15, work an incremental schedule priced 50 below 500, 45 from 500 and 40 from 1000. Band 1''s EOQ is 1032.795559. What does band 1 offer?', '["Its EOQ as the slides print it, 1,033", "No candidate, since its EOQ lies beyond its band", "The break quantity 500, as an all-units band", "The break quantity 1000, where the band ends"]'::jsonb, 1, 'Under an incremental schedule a band offers only its own EOQ, and only when that EOQ lies inside it. Band 1 runs from 500 to below 1000, and 1032.795559 lies above it, so band 1 gives no candidate. The slides print that EOQ as 1,033. An incremental band offers its own EOQ with A + Fi when that EOQ lies inside it, and no break quantity.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 9, 'On the incremental schedule of Caplice, lecture 8 slides 13 to 15, the engine orders 1789.000000 at a total of 98826.043879 a year, and the slides print 98,825. Why does the print sit just below the engine''s figure?', '["The slides take the effective unit price as 44.19 before costing each line", "The engine adds a fixed cost 7500.000000 the slides leave out", "The slides round each cost line and add the rounded lines", "The slides order 1788.854382"]'::jsonb, 2, 'The slide prints 44.19, 88,384, 559, 9,882, 98,825 and 105,000; it rounds each line, and its total is the sum of rounded lines. The engine sums the unrounded lines: purchase 88384.572387, ordering 558.971492 and holding 9882.500000. The slides print the same order of 1,789 and the same fixed cost of 7,500.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 10, 'A golden input states a demand of 100 a year, an order cost of 50, a holding rate of 1 and two all-units bands whose candidates both cost 200 a year. What does the engine return?', '["An order of 200 in band 1, as the larger lot buys at the lower price", "A refusal: the tie leaves the order undecided", "Two orders, one from each tied band", "An order of 100 in band 0, with its tie reason"]'::jsonb, 3, 'The engine compares the totals at 12 significant digits, finds 200.000000 and 200.000000 equal, and states its choice: order 100 at a total cost of 200 a year (band 0), the lowest of 2 candidates; tied on cost, the smaller quantity is taken. Taking the larger quantity is the alternative reading the engine names, and it is no refusal: a tie is a result.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 11, 'On the Caplice schedule, breaks at 500 and 1000 are stated with a rounding rule to the nearest multiple of 300. What does the engine return?', '["A refusal naming breaks[1].minQuantity, which must be a multiple of 300", "A refusal naming rounding.multiple, which must divide the demand of 2000 a year", "An order of 500 at the break, with the rounding rule set aside for a break quantity", "An order of 1789 as before, since the rounding acts only after a band is chosen"]'::jsonb, 0, 'The engine''s words: breaks[1].minQuantity must be a multiple of rounding.multiple 300, so that ordering at the break keeps its price; got 500. When a rule rounds, every break must be a multiple of the rounding multiple, and a policy that cannot work is refused before any figure is computed. The field named is the break.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 12, 'A schedule is stated whose first band starts at 10. What does the engine return?', '["An order as usual, with quantities below 10 priced at the first band''s price", "A refusal: breaks[0].minQuantity must be 0 so that every quantity has a price; got 10", "A refusal naming discountType, since a gapped schedule reads as neither type", "An order on the bands from 10 up, with a warning on small lots"]'::jsonb, 1, 'A schedule must price every quantity, so the first band must start at 0, and the engine refuses otherwise with the message quoted in the key. The discount type is refused only when it is missing or unknown.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 13, 'A schedule priced from 50 states a second band also priced at 50. What does the engine return, in its own words?', '["breaks[2].minQuantity must be above the band before it (500); got 500", "breaks[1].unitPrice must be a finite number above 0; got 0", "discountType must be ''all-units'' (the band''s price applies to the whole lot) or ''incremental'' (each unit is priced by its own band)", "breaks[1].unitPrice must be below the band before it (50); got 50"]'::jsonb, 3, 'Each band must be a real discount, so each price must fall; a second band at the same price is refused on breaks[1].unitPrice with the message in the key. The message about minQuantity 500 is the refusal of breaks that do not rise, the one about a price of 0 is the stated probe on a zero price, and the discountType message answers a missing type.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 14, 'A two-band schedule with prices of 1 and 0.5, the break at 100, and a demand, order cost and holding rate of 1 each is rounded down to a multiple of 100. What does the engine return?', '["An order of 100 at the break, since rounding down stops at the first break quantity", "An order of 1.414214, the band 0 EOQ, because a rule that gives nothing is skipped", "A refusal: the rounding gives an order of 0 from the band 0 EOQ 1.414214", "A refusal naming breaks[1].minQuantity, since the break is no multiple of the rounding"]'::jsonb, 2, 'The engine''s words: rounding gives an order quantity of 0 from the band 0 EOQ 1.414214; state a smaller multiple or another rule. A rounding rule that orders nothing is a policy that cannot work, and it is refused before any cost is computed. The break at 100 is a multiple of 100, so the break check passes.'),
  ('materials', 'intermediate', 'module', 'm01-quantity-discounts', 15, 'The lecture 8 three-band schedule is read as all-units in place of incremental, everything else as stated. What does the engine order?', '["1000.000000 at 86000.000000 a year", "1789.000000 at 98826.043879 a year, as under incremental", "500.000000 at 103062.500000", "400.000000 at 105000.000000"]'::jsonb, 0, 'On the schedule of lecture 8 slides 13 to 15 read as all-units, the engine orders 1000.000000 at 86000.000000 a year. All-units gives the band 2 price to every unit of the lot, so the best order sits on the break. Incremental orders 1789.000000 at 98826.043879, and 500.000000 at 103062.500000 is the answer to the two-band schedule of slide 12.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 1, 'The choke bean set CHK-BEAN on the Ekene register uses 3.3333 sets a month with a lead time of 2.5 months under continuous review. What demand over the protection period does the engine return?', '["3.3333 sets, one month of demand", "8.333250 sets, the demand a month times 2.5", "13.316294 sets, the demand the reorder point must cover at a cycle service level of 0.95", "11.666550 sets, the demand over 3.500000 months"]'::jsonb, 1, 'Under continuous review the protection period is the lead time alone, 2.5 months, and the demand over it is the demand a period times that period: 8.333250. 13.316294 is the reorder point, which adds the safety stock to that mean. 11.666550 is the demand over 3.500000 months, which needs a review period of 1.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 2, 'On CHK-BEAN the demand a month has a standard deviation of 1.6 and the lead time a standard deviation of 0.5 months. What sigma over the protection period does the engine return?', '["3.029476", "2.529822", "1.666650", "3.426036"]'::jsonb, 0, 'The engine''s rule is sigma = sqrt(P sd_d^2 + d^2 sd_L^2), and on the stated case it gives 3.029476. 2.529822 is what remains with the lead-time spread set to 0, and 1.666650 with the demand spread set to 0. 3.426036 is sigma when a review period of 1 month lengthens the protection period.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 3, 'In a stated probe on CHK-BEAN, the lead-time standard deviation is set to 0 and nothing else moves. What reorder point does the engine return at the cycle service level of 0.95?', '["12.494437, over a sigma of 2.529822", "13.316294, with the lead-time spread adding nothing to sigma", "11.074645, over 1.666650", "8.333250, the mean alone"]'::jsonb, 0, 'With the lead-time spread removed sigma falls to 2.529822, the safety stock to 4.161187 and the reorder point to 12.494437. 13.316294 is the stated case with both spreads, and 11.074645 over 1.666650 is the probe that removes the demand spread. The mean demand 8.333250 is the same in every row.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 4, 'Another probe removes the demand spread on the choke bean set and keeps its lead-time spread of 0.5 months. What safety stock comes back?', '["0.000000 sets", "4.161187 sets", "2.741395 sets", "4.983044 sets"]'::jsonb, 2, 'With the demand spread at 0, sigma is 1.666650, the demand a month times the lead-time spread, and the safety stock at k 1.644854 is 2.741395. Demand is certain only when both spreads are 0. 4.161187 is the other probe, and 4.983044 the stated case with both spreads.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 5, 'How does the engine combine the two parts of sigma on CHK-BEAN, 2.529822 from the demand spread and 1.666650 from the lead-time spread?', '["They add as they stand, so sigma is their plain sum", "Their squares add: 2.529822 squared plus 1.666650 squared is 3.029476 squared", "It keeps the larger part, 2.529822, and drops the smaller one as a rounding difference", "It multiplies them, since both spreads act over the same lead time"]'::jsonb, 1, 'The two sources are taken as independent, so their variances add and sigma is the square root of the sum: 2.529822 squared plus 1.666650 squared is 3.029476 squared. Standard deviations themselves do not add, and the engine keeps both parts in every call.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 6, 'A golden input states a steady demand of 20 a period with no spread and a lead time of 5 periods with a standard deviation of 1.5. What sigma does the engine return?', '["0.000000, as demand carries no spread", "100, the demand over the lead time, taken whole as the spread of that demand", "130, the reorder point the engine reports for this case under its stated rounding", "30.000000, the demand times the lead-time spread"]'::jsonb, 3, 'With the demand spread at 0 only the second term of the rule is left, d^2 sd_L^2, so sigma is the demand times the lead-time spread: 30.000000. A wandering lead time lets the mean demand run on for longer, so it sets a sigma of its own. 100 is the mean demand over the lead time and 130 the reorder point in the engine''s reason.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 7, 'A planner types the demand a week beside a lead time stated in days. What does the engine do with the two periods?', '["It converts nothing: every input is read in the one period the user chose", "It converts the lead time to weeks, taking a week as a stated number of days", "It refuses the call, naming the lead time as a period that does not match", "It converts the demand to days using the days a year of the case"]'::jsonb, 0, 'The demand, its spread, the lead time, its spread and the review period are all in the one period the user chooses; the engine does not convert. It has no field that states a period, so it cannot see a mismatch and it refuses nothing on that account. The period belongs in the written policy.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 8, 'Under periodic review the protection period is the review period plus the lead time. Where does the engine apply the stated lead-time spread?', '["To the whole protection period, review period included, as one spread", "To the review period only, since the count is what varies from week to week", "To the lead time only; the review period is fixed", "Nowhere under periodic review"]'::jsonb, 2, 'The lead-time spread enters on the lead time only; the review period is fixed. So a review period adds demand spread to sigma through P and leaves the lead-time term d^2 sd_L^2 as it was: on CHK-BEAN with a review period of 1, sigma rises from 3.029476 to 3.426036.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 9, 'Someone types -1 into the demand spread of the choke bean case by mistake. How does the calculation respond?', '["A sigma of 1.666650, treating the negative spread as no demand spread at all", "A sigma computed on the magnitude 1, since the square of -1 is the same as that of 1", "A refusal naming leadTimeSd, which must be stated whenever demandSd is below 0", "A refusal: demandSd must be a finite number at or above 0; got -1"]'::jsonb, 3, 'A standard deviation below zero means nothing, and the engine refuses it by name with the message in the key. It does not repair a stated input by dropping its sign or by setting it to 0, and the field it names is the one that was wrong.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 10, 'Both the lead time and the review period of the choke bean case are typed as 0. Which message stops the call?', '["A reorder point of 0.000000, since no demand arrives over a protection period of 0", "leadTime and reviewPeriod add to 0; the protection period must be above 0", "leadTime must be a finite number above 0; got 0", "A safety stock of 4.983044 over a demand of 0.000000"]'::jsonb, 1, 'With no lead time and no review period there is nothing to protect, and the engine refuses the policy by name with the message in the key. A reorder point of zero is never returned for this case. The message names leadTime as its field and states the condition on the sum of the two periods.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 11, 'The reorder point 13.316294 sits well above the safety stock 4.983044 on the choke beans. What makes up the difference?', '["It is the demand over the protection period, 8.333250, plus the safety stock", "It is the safety stock alone, carried to the next whole set", "It is the safety stock times the protection period of 2.5 months", "It is the demand a month, 3.3333, plus three safety stocks"]'::jsonb, 0, 'The engine''s rule is level = d P + k sigma: the reorder point is the demand over the protection period plus the safety stock, 8.333250 plus 4.983044. The safety stock is k times sigma, and this course names the safety stock and the reorder point apart.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 12, 'Tungsten carbide choke beans come in whole sets and the case rounds up to a multiple of 1. Which figure is held in place of 13.316294?', '["13.000000 sets", "13.316294 sets", "14.000000 sets", "15.000000 sets"]'::jsonb, 2, 'The engine''s reason ends: gives the reorder point s 13.316294, held as 14 (up to a multiple of 1). The stated rule rounds up, so the held level is 14.000000. Rounding to the nearest set is a different stated rule, and the engine applies the stated rule to the level it reports.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 13, 'What rule does the engine''s basis state for sigma, the standard deviation of demand over the protection period?', '["sigma = sd_d x P + d x sd_L, with the protection period taken as the lead time", "sigma = sqrt(sd_d^2 + sd_L^2), one variance from demand and one from the lead time", "sigma = sd_d x sqrt(P), with the lead-time spread left to the safety factor k", "sigma = sqrt(P sd_d^2 + d^2 sd_L^2) with P = leadTime + reviewPeriod"]'::jsonb, 3, 'The basis reads sigma = sqrt(P sd_d^2 + d^2 sd_L^2) with P = leadTime + reviewPeriod. The demand variance grows with P, the lead-time variance is scaled by the demand squared, and the two are added before the square root. Adding the spreads plainly or dropping the lead-time term gives a different figure.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 14, 'The fixture''s note on the CHK-BEAN case is quoted below. In what period are its demand, lead time and spreads stated?

> periods are months; lead time 2.5 months with a standard deviation of 0.5 months', '["Weeks, the period the lecture 11 checks use for the same rule", "Months, for the demand, its spread, the lead time and its spread alike", "Days for the lead time and months for the demand", "Years, since the register states usage a year"]'::jsonb, 1, 'The fixture''s note says the periods are months, and the engine reads every input in that one period. The lecture 11 checks are worked in weeks, and the register''s annual usage column is a year, but neither sets the period of this case.'),
  ('materials', 'intermediate', 'module', 'm02-demand-over-the-lead-time', 15, 'An extra key named zFactor is slipped into the choke bean call to force the safety factor. How is it handled?', '["The reorder point as usual, with zFactor read as the safety factor k in place of the one from the level", "The reorder point as usual, with the unknown key zFactor silently dropped from the call", "A refusal naming zFactor as a key it does not accept, before any input is read", "A refusal naming serviceLevel, which zFactor would replace"]'::jsonb, 2, 'Every call refuses an input key the function does not read, naming the key and the full list of accepted keys: zFactor is not an accepted key; the accepted keys at the top level are demandMean, demandSd, leadTime, leadTimeSd, reviewPeriod, serviceMeasure, serviceLevel, orderQuantity, safetyFactorRounding, minimumSafetyFactor, rounding. A misspelt or extra key is never dropped silently.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 1, 'A stores policy targets a cycle service level. Which event is that target a probability of?', '["The fraction of demand met from stock over a year", "The share of items in the register that are never short", "The probability of no stockout in a replenishment cycle", "The expected units short a cycle, divided by the order quantity"]'::jsonb, 2, 'The cycle service level is the probability of no stockout in a replenishment cycle, and the engine''s own words for the measure are ''cycle-service'' (probability of no stockout in a replenishment cycle). The fraction of demand met from stock is the fill rate, the second measure, which is one less the units short a cycle over the order quantity.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 2, 'Which safety factor k turns the choke bean target of 0.95, read as a cycle service level, into stock?', '["1.644854, the inverse standard normal at 0.95", "1.026327, the factor the same item needs at a fill rate of 0.98", "1.64, the factor as a printed table reads it", "1.959964"]'::jsonb, 0, 'The engine''s reason reads: a cycle service level of 0.95 gives k = Phi^-1(0.95) = 1.644854. The case states the safety factor reading as none, so no table reading applies; 1.64 would need the reading to two decimals. 1.026327 answers a fill rate of 0.98, a different target, and 1.959964 is the factor at 0.975.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 3, 'A stated probe lifts the choke bean target to 0.99, changing nothing else. How much safety stock is that?', '["2.326348 sets", "15.380864 sets", "16.000000 sets", "7.047614 sets"]'::jsonb, 3, 'At 0.99, k is 2.326348, and the safety stock is k times sigma 3.029476: 7.047614. The reorder point adds the demand over the protection period, 15.380864, and the stated rounding up to a whole set holds it as 16.000000. The factor k itself is no quantity of stock.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 4, 'Rounding the choke bean reorder point 13.316294 up to 14.000000 changes the protection it gives. What achieved figure is reported?', '["0.95 exactly, the stated target, whatever level the rounding rule holds", "0.969295, above the target, since rounding up raises the service", "0.983436, the achieved service of the Poisson PSV kits", "0.886929, the cycle service of the held fill-rate level"]'::jsonb, 1, 'The engine reports the service a held level achieves beside the target: at 0.95 the held level 14.000000 achieves 0.969295. 0.983436 belongs to the PSV kits at level 5, and 0.886929 is the cycle service at the level CHK-BEAN holds for a fill rate of 0.98.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 5, 'A stated probe sets CHK-BEAN''s cycle service level to 0.8. What reorder point is held, and what cycle service does it achieve?', '["Held as 10.882921, achieving 0.8 exactly with no rounding", "Held as 13.000000, achieving 0.938274 over the stated target", "Held as 11.000000, achieving 0.810643", "Held as 11.000000, achieving 0.8 exactly"]'::jsonb, 2, 'At 0.8 the reorder point is 10.882921, held as 11.000000 under the stated rule of rounding up to a whole set, and the service at 11 is 0.810643. The target 0.8 is met with room to spare, and 13.000000 at 0.938274 is the row for a level of 0.9.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 6, 'A planner asks for a cycle service level of 1 on the choke beans, meaning no stockout ever. What happens?', '["A refusal on serviceLevel, a probability strictly inside 0 to 1", "A reorder point at the largest level a normal table prints", "A reorder point of 16.000000, the held level at 0.99", "A refusal naming serviceMeasure, which cannot promise no stockout"]'::jsonb, 0, 'A cycle service level is a probability strictly between 0 and 1. Normal demand has no ceiling, so no finite reorder point meets a level of 1, and the engine refuses it by name, in its own words: serviceLevel must be a number strictly between 0 and 1; got 1. It picks no level of its own.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 7, 'For a cycle service target, what algorithm supplies the inverse normal behind k?', '["The normal curve read from a two-decimal table built into the engine", "A Monte Carlo draw of the normal curve on a stated seed", "A bisection on the unit normal loss G(k), the method for a fill rate", "An exact inverse normal, Phi^-1 by Wichura AS241"]'::jsonb, 3, 'The basis reads: Phi^-1 by Wichura AS241; Phi through the regularised incomplete gamma (engines/hse/safetyStats.js); the fill-rate k by bisection to the last binary digit. The engine keeps no table of its own, draws no sample here, and keeps the bisection for the fill rate.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 8, 'The start "Lead-time spread alone" in the stock calculator reads its safety factor from a table to whole numbers at a cycle service level of 0.9. How much safety stock results?', '["130, the level held at k read as 1", "30.000000, with k read as 1", "30.000000, with the exact k of 1.281552", "0.000000, with k read as 0"]'::jsonb, 1, 'The reason reads: a cycle service level of 0.9 gives k = Phi^-1(0.9) = 1.281552, read as 1; safety stock 30 over a demand of 100 with sigma 30. Read to whole numbers, 1.281552 becomes 1, so the safety stock equals sigma, 30.000000. 130 is the level held, and a factor of 0 would need a reading that rounds down.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 9, 'Caplice, lecture 11 slide 24, prints a safety stock at a cycle service level of 0.95 on the weekly data. With k read from a table to two decimals and the level held to the nearest unit, what level does the engine hold?', '["830.000000, the level the table reading holds at 0.90", "839.179604, the reorder point of the fill-rate rule at 0.95", "923.000000, the printed 423 above the demand of 500.000000", "923.000000, the exact k giving a safety stock of 424.518354"]'::jsonb, 2, 'Read to two decimals, k is 1.64, and the level held to the nearest unit is 923.000000. Less the demand over the two-week lead time, 500.000000, that is the printed 423. The exact k gives a safety stock of 424.518354, which misses the print. 839.179604 belongs to the fill-rate column of the same slide, and 830.000000 to the 0.90 row.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 10, 'At 0.99 the cycle service column of Caplice, lecture 11 slide 24, prints 601. Worked with the exact factor and no rounding, how much safety stock comes out?', '["A safety stock of 600.404410, which misses the print by less than a unit", "A safety stock of 601.000000, which matches the print", "A safety stock of 512.349286, the fill-rate figure at 0.99", "A safety stock of 1101.000000, the level the table reading holds"]'::jsonb, 0, 'With the exact k the engine''s safety stock at 0.99 is 600.404410. The table reading, k read as 2.33 and the level held as 1101.000000, reproduces the printed 601. 512.349286 is the fill-rate figure at 0.99, and 1101.000000 is a held level, of which the safety stock is only the part above the mean.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 11, 'Caplice, lecture 11 slides 18 to 24, state a forecast error of 1,316 units a year. What weekly standard deviation do the golden inputs read it as?', '["1,316 unchanged, since the engine converts the year to weeks itself", "258.088834, the sigma over the two-week lead time", "250.000000, the weekly demand", "182.496365, the error over the square root of 52"]'::jsonb, 3, 'The golden inputs read the slides in weeks: a demand of 250.000000 a week with a standard deviation of 182.496365, the RMSE over the square root of 52. The engine converts no period, so the scaling happens before the figure is typed. 258.088834 is sigma over the two weeks, which the engine computes from it.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 12, 'Seven decimals are requested for the safety-factor table reading on the choke beans. Which message comes back?', '["The safety factor 1.644854 read to 7 decimals and used as it stands", "safetyFactorRounding.decimals must be a whole number from 0 to 6; got 7", "safetyFactorRounding must be { rule: ''none'' } or { rule: ''nearest'', decimals } (a table read to that many decimals)", "A reorder point of 13.316294, with the reading capped silently at 6 decimals"]'::jsonb, 1, 'The engine reads a factor to at most 6 decimals, its cap MAX_DECIMALS, and refuses 7 by name on safetyFactorRounding.decimals with the message in the key. It caps nothing silently. The message about { rule: ''none'' } answers a reading that is missing or malformed.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 13, 'CHK-BEAN is stated with the safety factor reading { rule: ''none'' } and decimals 2 beside it. What does the engine return?', '["k read as 1.64, since the decimals override the rule", "The exact k of 1.644854, with the decimals ignored", "safetyFactorRounding.decimals must be a whole number from 0 to 6; got 2", "safetyFactorRounding.decimals must be left out when the rule is ''none''"]'::jsonb, 3, 'A rule of none reads no table, so a decimals figure beside it is a contradiction, and the engine refuses it with the message in the key. It neither follows the decimals nor drops them. The range message answers decimals outside 0 to 6, and 2 lies inside it.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 14, 'The service measure control is left blank on the choke bean case. Quote the engine''s response.', '["serviceMeasure must be ''cycle-service'' (probability of no stockout in a replenishment cycle) or ''fill-rate'' (fraction of demand met from stock)", "A reorder point at the cycle service level of 0.95, the measure the engine takes when a case states a level alone", "serviceLevel must be a number strictly between 0 and 1; got 0.95", "orderQuantity is required for a fill rate (units short are measured against the quantity each cycle brings)"]'::jsonb, 0, 'A service level in this course always names its measure, and the engine refuses a call that does not, naming the two measures it knows. It supplies no measure of its own. The serviceLevel message answers a level outside 0 to 1, and the orderQuantity message a fill rate stated with no order quantity.'),
  ('materials', 'intermediate', 'module', 'm03-the-cycle-service-level', 15, 'On the lecture 11 data, why does the course state which safety-factor reading a published safety stock uses?', '["The exact k is a slip that the table reading repairs in each of the four rows", "The table reading is the engine''s fixed practice for every published case it checks", "The table reading reproduces all four printed figures and the exact k does not", "The two readings agree at every level, so stating one is a matter of style"]'::jsonb, 2, 'The table reading reproduces all four printed figures (601, 423, 330 and 217); the exact safety factor does not, which is why the course states the rule a figure was read with. Neither is a slip: each answers a differently stated question. The reading is a stated input, safetyFactorRounding.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 1, 'Of the two service measures, the item fill rate is one. What does it express?', '["The probability of no stockout in a replenishment cycle", "The share of orders that arrive within the stated lead time", "The fraction of cycles in which some demand is short", "The fraction of demand met from stock"]'::jsonb, 3, 'In the engine''s own list of measures, ''fill-rate'' is the fraction of demand met from stock; a chance of no stockout per cycle belongs to the other measure, the cycle service level. A fill rate counts units short against the order quantity each cycle brings, so a cycle short by a fraction of a unit barely moves it.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 2, 'CHK-BEAN is stated at a fill rate of 0.98 with an order quantity of 12, every other input as in the fixture case. What safety factor k does the engine return?', '["1.644854", "1.026327", "2.326348", "0.841621"]'::jsonb, 1, 'The reason reads: a fill rate of 0.98 needs G(k) at or below 12 x (1 - 0.98) / 3.029476 = 0.079222, so k = 1.026327. 1.644854 is the factor for a cycle service level of 0.95 on the same item, 2.326348 for a cycle service level of 0.99 and 0.841621 for one of 0.8.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 3, 'For CHK-BEAN at a fill rate of 0.98, what target on the unit normal loss G(k) does the engine print in its reason?', '["0.079222, from 12 x (1 - 0.98) / 3.029476", "0.173279, the loss target of the lecture 12 periodic review", "0.98, the stated fill rate taken as the target itself", "0.044171, the target of the lecture 11 case at 0.95"]'::jsonb, 0, 'A fill rate p with order quantity Q allows at most Q times one less p units short a cycle; divided by sigma, that is the target on G: 12 x (1 - 0.98) / 3.029476 = 0.079222. 0.173279 is the lecture 12 target, and 0.044171 the target for the lecture 11 data at a fill rate of 0.95 with an order quantity of 228.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 4, 'Once 12.000000 sets are held for the 0.98 fill-rate target on the choke beans, which two achieved service figures are printed?', '["A fill rate of 0.98 and a cycle service of 0.98, the one stated target read on both measures", "A fill rate of 0.886929 and a cycle service of 0.986135", "A fill rate of 0.986135 and a cycle service of 0.886929", "A fill rate of 0.986135 and a cycle service of 0.969295"]'::jsonb, 2, 'At the held level the engine reports an achieved fill rate of 0.986135 and an achieved cycle service of 0.886929. The same level meets the fill rate with room to spare and leaves more than one cycle in ten with some shortage, because most short cycles are short by a fraction of a set. 0.969295 is the cycle service of the level held for a cycle service level of 0.95.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 5, 'How many sets short a cycle does the engine expect on the choke bean set once its 0.98 fill-rate level is held?', '["11.400000 sets, as on the lecture 11 case", "0.166382 sets a cycle, out of the 12 each order brings", "3.109233 sets, the safety stock at that level", "0.022488 sets"]'::jsonb, 1, 'At the held level of 12.000000 the expected units short a cycle are 0.166382, which is how the fill rate reaches 0.986135 against the 12 sets each order brings. 3.109233 is the safety stock, and 0.022488 is the expected units short of the PSV kits at level 5.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 6, 'The fill-rate choke bean case is loaded with its order quantity cleared. What message appears?', '["A safety factor of 1.026327, since the order quantity of 12 sits in the Ekene fixture already", "orderQuantity must be a finite number above 0; got undefined", "A reorder point computed at the cycle service level, the measure that needs no order quantity", "orderQuantity is required for a fill rate (units short are measured against the quantity each cycle brings)"]'::jsonb, 3, 'A fill rate measures units short against the quantity each cycle brings, so the order quantity sits in the sum and the engine refuses its absence with the message in the key. It never switches measure on its own. The message about a finite number above 0 answers an order quantity stated as 0, and it prints got 0.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 7, 'Ten units a period with no spread and three periods of lead time with no spread: a fill rate of 0.95 on an order of 10 is asked of this certain demand. What is the outcome?', '["A refusal: demand over the protection period is certain, so a fill rate sets no safety factor", "A reorder point of 30.000000 with a safety factor of 1.644854, as the cycle service level gives", "A safety factor of 0.000000, the smallest k that meets any fill-rate target on certain demand", "A safety stock of 0.000000 and a fill rate of 1"]'::jsonb, 0, 'The engine''s words: demandSd and leadTimeSd are both 0, so demand over the protection period is certain and a fill rate sets no safety factor. A fill rate protects against uncertainty, and with none there is nothing for k to solve. A cycle service target on the same certain demand is accepted and gives the reorder point 30.000000.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 8, 'Caplice, lecture 11 slide 24, prints a safety stock of 348 at an item fill rate of 0.95 on the weekly data with an order quantity of 228. How does the course treat that figure?', '["As the rule''s own figure, which the engine reaches with k read from a table to two decimals", "As proof the engine is off by 8.820396 and needs a new rule", "As a slip: the fill-rate rule gives 339.179604", "As a correct figure for a different order quantity"]'::jsonb, 2, 'The fill-rate rule on the same inputs needs G(k) at or below 228 x (1 - 0.95) / 258.088834 = 0.044171, so k = 1.314197 and the safety stock is 339.179604, 8.820396 below the print. The other three rows agree to within 2 units. The course keeps the print beside the rule''s figure and keeps the rule as it is.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 9, 'At its own safety stock of 339.179604 on the slide 24 case at 0.95, what fill rate and units short does the engine report?', '["An achieved fill rate of 0.95 only after the stock is raised to the printed 348", "An achieved fill rate of 0.950000, with 11.400000 units short a cycle", "An achieved fill rate of 0.986135, as on the choke bean set", "An achieved fill rate of 0.99"]'::jsonb, 1, 'At the engine''s safety stock the achieved fill rate is 0.950000 and the expected units short a cycle are 11.400000: the rule meets its target exactly. Raising the stock to the printed 348 would overshoot it. 0.986135 is the choke bean set''s achieved fill rate at 0.98, and 0.99 is the target of a different row of the column.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 10, 'Caplice, lecture 11 slide 24, prints 513 for a fill rate of 0.99. What figure does the bisection give?', '["513, as printed, with k read from a table to two decimals", "600.404410, with the cycle service k 2.326348", "601.000000, as printed for 0.99 on the slide", "512.349286, with k 1.985166 from the bisection on G(k)"]'::jsonb, 3, 'Solving for k by bisection gives 1.985166 and a safety stock of 512.349286, which agrees with the printed 513 to within a unit, as three rows of the column do. 600.404410 and 601 are the cycle service column at 0.99, a different measure on the same slide.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 11, 'Which numerical method finds k when the target is a fill rate, as the basis records it?', '["The fill-rate k by Phi^-1 at the stated rate, as for a cycle service level", "The fill-rate k from a two-decimal table of G(k)", "The fill-rate k by bisection to the last binary digit", "The fill-rate k by a seeded Monte Carlo over normal draws"]'::jsonb, 2, 'For a fill rate the basis records bisection to the last binary digit. G falls as k rises, so the engine takes the smallest k that meets the target. The inverse normal serves the cycle service level only.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 12, 'What does the engine''s rule give for the expected units short per cycle and the fill rate P2?', '["sigma G(k), G(k) = phi(k) - k (1 - Phi(k)); P2 = 1 - sigma G(k) / Q", "sigma (1 - Phi(k)); P2 = Phi(k), the chance that a cycle has no stockout", "k sigma / Q; P2 = 1 - k sigma / Q", "G(k) / sigma; P2 = 1 - Q G(k) / sigma, the loss scaled up by the order"]'::jsonb, 0, 'The basis reads: expected units short per cycle = sigma G(k), G(k) = phi(k) - k (1 - Phi(k)); P2 = 1 - sigma G(k) / Q. Phi(k) is P1, the cycle service level, a different measure. The safety stock k sigma is no count of units short.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 13, 'On CHK-BEAN, a cycle service level of 0.95 gives k 1.644854 and a fill rate of 0.98 gives k 1.026327. Which target asks for more safety stock, and why?', '["The fill rate of 0.98, since 0.98 is the higher of the two stated levels", "Neither, since both are the same kind of service target", "The fill rate, since it counts units short against the order", "The cycle service level of 0.95, whose k of 1.644854 is the larger"]'::jsonb, 3, 'The engine computes k 1.644854 for the cycle service level of 0.95 and k 1.026327 for the fill rate of 0.98 on the same sigma, 3.029476, so the cycle service target asks for the larger safety stock: a reorder point of 13.316294 against 11.442483. Comparing the two stated levels as one scale is the mistake the vocabulary rule prevents.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 14, 'What safety stock and reorder point go with k 1.026327 on the choke beans?', '["Safety stock 4.983044, reorder point 13.316294, as at a cycle service level of 0.95", "Safety stock 3.109233, reorder point 11.442483", "Safety stock 3.109233, reorder point 3.109233", "Safety stock 11.442483, reorder point 12.000000"]'::jsonb, 1, 'The reason reads: safety stock 3.109233 over a demand of 8.33325 with sigma 3.029476 gives the reorder point s 11.442483, held as 12. The reorder point adds the safety stock to the demand over the protection period, so it is never equal to the safety stock here. 12.000000 is the held level.'),
  ('materials', 'intermediate', 'module', 'm04-the-fill-rate', 15, 'How close does the engine come to Caplice, lecture 11 slide 24, at the lowest printed fill rate, 0.80?', '["A safety stock of 217.213043, against the printed 217, from the cycle service column", "A safety stock of 250.102945 against the printed 252", "A safety stock of 147.444755 against the printed 148", "A safety stock of 339.179604 against the printed 348"]'::jsonb, 2, 'At 0.80 the engine''s k is 0.571295 and the safety stock 147.444755; the slide prints 148, within 2 units. 250.102945 against 252 is the 0.90 row, 339.179604 against 348 is the 0.95 row and its slip, and 217.213043 is the exact cycle service figure at 0.80.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 1, 'Counting the choke bean bin once a month adds a review period of 1 to the lead time of 2.5. Which protection period and policy name come back?', '["3.500000 months, policy periodic (R, S)", "2.5 months, policy continuous (s, Q), as the review period adds nothing", "1 month, the review period alone", "3.500000 months, policy continuous (s, Q)"]'::jsonb, 0, 'Under periodic review the protection period becomes the review period plus the lead time, 3.500000 months, and the engine names the policy periodic (R, S). Stock raised at one count must last until the next count and then until that order lands. A review period of 0 is continuous review.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 2, 'Monthly counts lengthen the choke bean protection period. What standard deviation of demand over it is computed?', '["3.426036", "3.029476", "2.529822", "5.635328"]'::jsonb, 0, 'Over 3.500000 months the demand term of the rule grows with P while the lead-time term stays, so sigma rises from 3.029476 to 3.426036. 2.529822 is the demand part of sigma over 2.5 months alone, and 5.635328 is the safety stock at the review period of 1.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 3, 'Reviewed monthly, the choke bean set gets an order-up-to level S. What is S, and what is it held as?', '["13.316294, held as 14.000000, the reorder point", "17.301878, held as 18.000000 by the rule up", "11.666550, the demand over 3.500000 months", "17.301878, held as it stands with no rounding"]'::jsonb, 1, 'The reason reads: safety stock 5.635328 over a demand of 11.66655 with sigma 3.426036 gives the order-up-to level S 17.301878, held as 18 (up to a multiple of 1). The stated rule rounds up. 13.316294 is the continuous-review reorder point, and 11.666550 is the mean demand the level covers before its safety stock.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 4, 'CHK-BEAN moves from continuous review to a review period of 1 month at the same cycle service level of 0.95. What happens to the safety factor k?', '["It rises to 1.959964 to cover the longer protection period", "It falls to 1.026327, since each count tops the stock up", "It is read as 1.64, the table figure periodic review uses", "It stays at 1.644854, since the stated level is the same"]'::jsonb, 3, 'The safety factor comes from the stated cycle service level alone, so it stays at 1.644854 under both policies. What grows is sigma, from 3.029476 to 3.426036, and with it the safety stock, from 4.983044 to 5.635328. 1.959964 is the factor at 0.975 and 1.026327 the factor at a fill rate of 0.98.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 5, 'Monthly counting on the choke bean set: how much stock does k times sigma come to over its protection period of 3.500000?', '["4.983044 sets", "17.301878 sets", "5.635328 sets", "11.666550 sets"]'::jsonb, 2, 'The safety stock is k times sigma over the protection period: 1.644854 times 3.426036 is 5.635328. 4.983044 is the continuous-review safety stock, 17.301878 is the order-up-to level and 11.666550 the mean demand over 3.500000 months.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 6, 'Caplice, lecture 12 slides 5 and 6, work a periodic review on the weekly lecture 11 data with a review period of 8 weeks, a fill rate of 0.95 and an order quantity of 2000. What sigma does the engine return, against the slide''s printed 577?', '["577.104177 over a protection period of 10 weeks", "258.088834 over the lead time of 2 weeks, since a review period adds no spread", "577.104177 over the review period of 8 weeks alone", "2500.000000 over 10 weeks"]'::jsonb, 0, 'The protection period is the review period plus the lead time, 10 weeks, and sigma over it is 577.104177, which the slide prints as 577. 258.088834 is sigma over the two-week lead time of the lecture 11 check, and 2500.000000 is the mean demand over the 10 weeks.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 7, 'Slides 5 and 6 of lecture 12 print a safety factor of 0.58. What does the engine hold as k, exact and as read?', '["0.58 exact, as printed on the slide, with no reading needed", "1.314197 exact, the lecture 11 fill-rate factor", "0.173279 exact, the loss target", "0.583373 exact, read as 0.58"]'::jsonb, 3, 'The reason reads: so k = 0.583373, read as 0.58. The slide prints 0.58, which the stated table reading reproduces. 0.173279 is the target on G that k must meet, and 1.314197 is the exact factor of the lecture 11 case at a fill rate of 0.95.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 8, 'What order-up-to level does the engine return on the case of Caplice, lecture 12 slides 5 and 6, and what does the slide print?', '["2835.000000 exact, which the slide prints unrounded", "2834.720422, held as 2835.000000 against the printed 2835", "2500.000000, the mean demand over the protection period", "2834.720422, held as it stands"]'::jsonb, 1, 'The reason reads: gives the order-up-to level S 2834.720422, held as 2835 (the nearest multiple of 1 (halves upward)). The stated rule is the nearest whole unit, so the held level 2835.000000 matches the print. 2500.000000 is the mean demand the level covers.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 9, 'Why does the lecture 12 case state an order quantity of 2000 for its fill rate?', '["It is the demand over one review period, stated as an input", "The engine computes it from the review period and the demand", "It is the order-up-to level less the safety stock", "It is the demand over the protection period of 10 weeks"]'::jsonb, 0, 'The golden input states an order quantity of 2000, the demand over one review period of 8 weeks at 250 a week. The engine does not work it out; it is a stated input, and the fill rate measures units short against it. The demand over the 10-week protection period is 2500.000000.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 10, 'Weekly lecture 11 data, a requested cycle service level of 0.4, and a stated floor of 0 on k: what does the engine produce?', '["k of -0.253347, a safety stock of -65.386058 and a reorder point of 434.613942", "A refusal: a level below one half is no policy", "k held at the floor 0, so the reorder point equals the mean 500", "k of 1.644854, as at a level of 0.95"]'::jsonb, 2, 'The reason reads: a cycle service level of 0.4 gives k = Phi^-1(0.4) = -0.253347; below the stated minimum 0, so k = 0; safety stock 0 over a demand of 500 with sigma 258.088834 gives the reorder point s 500. The negative safety stock is what the same call returns with no floor. A level of 0.4 is a valid probability and is not refused.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 11, 'Same 0.4 request, but the floor is typed as null and the rounding rule is none. What comes back now?', '["A safety stock of 0.000000 and a reorder point of 500.000000", "A refusal: minimumSafetyFactor must be a stated number or null for no floor; got null", "A safety stock of 65.386058, the magnitude of the negative figure", "A safety stock of -65.386058 and a reorder point of 434.613942"]'::jsonb, 3, 'With no floor the engine uses the negative k as it is: safety stock -65.386058 over a demand of 500 with sigma 258.088834 gives the reorder point s 434.613942, held as 434.613942 (no rounding). Null is an accepted statement of no floor; the refusal is for a floor left out, and it prints got undefined.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 12, 'A call on CHK-BEAN leaves minimumSafetyFactor out altogether. What does the engine return?', '["A reorder point as usual, since the stated level of 0.95 gives a positive k anyway", "minimumSafetyFactor must be a stated number or null for no floor; got undefined", "A reorder point computed with a floor of 0, the usual practice for safety stock", "safetyFactorRounding must be { rule: ''none'' } or { rule: ''nearest'', decimals } (a table read to that many decimals)"]'::jsonb, 1, 'The floor is a stated input with no default: a number, or null for no floor. Leaving it out is refused by name even where the floor would not act, as at 0.95, where k is 1.644854. The safetyFactorRounding message answers a missing table reading.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 13, 'Demand of 10 each period with zero spread meets a lead time of 3 periods with zero spread. At a cycle service target of 0.95 and the rounding rule none, which figures result?', '["Sigma 0.000000, safety stock 0.000000, reorder point 30.000000", "A refusal, since certain demand leaves nothing to protect", "Sigma 0.000000, safety stock 1.644854, the factor itself", "Sigma 0.000000 and a reorder point of 10, one period of demand"]'::jsonb, 0, 'The reason reads: a cycle service level of 0.95 gives k = Phi^-1(0.95) = 1.644854; safety stock 0 over a demand of 30 with sigma 0 gives the reorder point s 30. The safety stock is k times sigma, so it is 0.000000 whatever k is. A cycle service target is accepted on certain demand; only a fill rate is refused there.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 14, 'On the certain-demand case, the engine still prints a safety factor of 1.644854. Why does the reorder point stay at 30.000000?', '["Because the engine sets k to 0 whenever demand is certain", "Because a floor of 0 on the safety factor holds it there", "Because the reorder point is rounded down to the demand", "Because the safety stock is k times sigma, and sigma is 0"]'::jsonb, 3, 'With no demand spread and no lead-time spread sigma is 0.000000, so the safety stock k times sigma is 0.000000 for any k, and the reorder point is the demand over the lead time, 30.000000. The engine keeps k at 1.644854 in its reason, and the case states the rounding rule none.'),
  ('materials', 'intermediate', 'module', 'm05-periodic-review', 15, 'The engine''s basis cites its sources for safety stock under periodic review. What does it say changes under (R, S)?', '["k is recomputed from the review period", "Q becomes the order-up-to level S, and sigma is unchanged", "L becomes R + L, and the rest of the rule is unchanged", "The lead-time spread applies to R + L as one period"]'::jsonb, 2, 'The basis reads: Caplice, MIT ESD.260J (2006) lecture 11 (s = xL + k sigmaL; P1 = Phi(k); P2 = 1 - sigmaL G(k) / Q) and lecture 12 ((R, S): L becomes R + L). The protection period grows and every other part of the rule stays. The lead-time spread enters on the lead time only; the review period is fixed.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 1, 'Why does the engine read the demand of a slow mover as Poisson?', '["Its demand has no spread, so a normal curve would give a sigma of 0", "Its demand over the lead time is a small whole number, and a normal curve puts weight below zero", "The Poisson level is always lower than the normal reorder point for the same item", "A slow mover''s lead time is too long for the normal safety stock to accept"]'::jsonb, 1, 'A slow mover is used a unit or two at a time, a few times a year; demand over the lead time is a small whole number, and a normal curve puts weight below zero. The engine reads such demand as Poisson with the mean over the protection period. A Poisson demand does have a spread, and the engine sets no cap on a normal lead time.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 2, 'The PSV kits on the Ekene register are used at 0.5 kits a month with a lead time of 4 months under continuous review. What Poisson mean does the engine use?', '["0.500000 kits", "6 kits", "5 kits", "2.000000 kits"]'::jsonb, 3, 'The mean is the demand rate a period times the lead time plus the review period: 0.5 times 4 is 2.000000. 0.5 is the rate for one month, 6 kits is the usage a year the fixture''s note gives, and 5 is the level the engine chooses at a cycle service level of 0.95.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 3, 'Which reason does the engine print when choosing the PSV kit level at 0.95?', '["level 5: P(X <= 5) = 0.983436 is at or above 0.95; at 4 it is 0.947347 (Poisson mean 2)", "level 4: P(X <= 4) = 0.947347 is at or above 0.95, within the tolerance the engine allows", "level 3: expected units short 0.218018 is at or below 6 x (1 - 0.95) = 0.3", "level 2: the mean demand over the lead time, with no stock held above it"]'::jsonb, 0, 'The engine walks up the whole levels and takes the smallest whose cumulative probability is at or above the target: 0.947347 at level 4 falls short of 0.95, and 0.983436 at level 5 meets it. The level 3 reason is the fill-rate answer with an order quantity of 6, a different measure.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 4, 'At level 5 on the PSV kits, what safety stock and achieved cycle service does the engine report?', '["Safety stock 5 kits, achieved cycle service 0.95", "Safety stock 3.000000, achieved cycle service 0.95", "Safety stock 3.000000, achieved cycle service 0.983436", "Safety stock 2.000000, achieved cycle service 0.947347"]'::jsonb, 2, 'The safety stock is the level less the mean, 5 less 2.000000, which is 3.000000, and the service achieved at level 5 is its cumulative probability, 0.983436, above the stated 0.95. The whole level is no safety stock, and 0.947347 belongs to level 4.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 5, 'The PSV kits are stated at a fill rate of 0.95 with an order quantity of 6 kits. What level does the engine return, and what fill rate does it achieve?', '["Level 5, the same as at a cycle service level of 0.95", "Level 3, achieving a fill rate of 0.963664", "Level 3, achieving a fill rate of exactly 0.95", "Level 2, achieving a fill rate of 0.963664"]'::jsonb, 1, 'The reason reads: level 3: expected units short 0.218018 is at or below 6 x (1 - 0.95) = 0.3; at 2 it is 0.541341 (Poisson mean 2). The achieved fill rate is 0.963664. Level 5 answers the cycle service level of 0.95; the two measures give different levels, and level 2 fails with 0.541341 short.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 6, 'The engine builds the expected units short column by the loss recursion. On the PSV kits, L(0) is 2.000000 and F(0) is 0.135335. What is L(1)?', '["0.406006", "0.270671", "0.541341", "1.135335"]'::jsonb, 3, 'The rule is L(0) = m, L(x + 1) = L(x) - (1 - F(x)): L(1) is 2.000000 less one less 0.135335, which is 1.135335. 0.270671 is the probability of exactly one kit, and 0.541341 is L(2). 0.406006 is the cumulative probability F(1).'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 7, 'Caplice, lecture 13 slide 12, prints the expected units short beyond level 4 as 0.009 on a Poisson mean of 0.8. How does the course treat that figure?', '["As a slip: the recursion the slide itself states gives 0.001619 at level 4", "As the rule''s figure, which the engine prints as 0.001619 only because it rounds to six decimals", "As a correct figure, since 0.009 is 0.010699 at the precision the slide uses", "As a figure the engine cannot check, since level 4 lies beyond the slide''s fill-rate level of 2"]'::jsonb, 0, 'The loss at level 3 is 0.010699 and the cumulative probability there is 0.990920, so 0.010699 less one less 0.990920 is 0.001619, the engine''s figure at six decimals. The printed 0.009 is not the recursion''s figure at any precision the slide uses, and the course keeps the print beside the rule''s figure.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 8, 'The lecture 13 slow mover: 0.8 a week, weekly reviews, zero lead time, fill rate 0.9 on an order of 0.8. Which level satisfies it?', '["Level 1, with 0.249329 units short against an allowance of 0.08", "Level 3, with 0.010699 units short, the first level under 0.08 by a clear margin", "Level 2, with 0.058121 units short against an allowance of 0.08", "Level 4, the first level whose cumulative probability passes 0.99"]'::jsonb, 2, 'The reason reads: level 2: expected units short 0.058121 is at or below 0.8 x (1 - 0.9) = 0.08; at 1 it is 0.249329 (Poisson mean 0.8). Lecture 13 slides 11 and 12 print the same level of 2. The engine takes the smallest level that meets the target, and level 1 misses it.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 9, 'A stated case sets a cycle service target on a Poisson mean of 1 equal, to its last digit, to the cumulative probability at level 1 itself. What does the engine return?', '["Level 2, as a target equal to the cumulative probability is met only strictly above", "Level 1, the target met at or above it, the engine''s stated reading", "Level 0, whose cumulative probability 0.367879 is the nearest", "A refusal, since a target equal to a table figure is ambiguous"]'::jsonb, 1, 'The reason reads: "level 1: P(X <= 1) = 0.735759 is at or above 0.7357588823428847; at 0 it is 0.367879 (Poisson mean 1)". The engine compares at 12 significant digits and meets the target at or above it. A target met only strictly above is the alternative reading the engine names; under it the answer would be level 2.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 10, 'Raise that target to 0.7358 on the same mean. Which level answers?', '["Level 1, as 0.735759 rounds to 0.7358 at four decimals", "Level 1, with a cumulative probability of 0.735759", "Level 3", "Level 2, with a cumulative probability of 0.919699"]'::jsonb, 3, 'The reason reads: level 2: P(X <= 2) = 0.919699 is at or above 0.7358; at 1 it is 0.735759 (Poisson mean 1). Level 1 falls short of 0.7358, and the engine compares at 12 significant digits, so no rounding to four decimals helps it. Level 3 is more than the target needs.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 11, 'How much stock does the engine hold for an item whose Poisson mean is only 0.05, when the stated cycle service target is 0.9?', '["Level 0, since P(X <= 0) = 0.951229 already meets 0.9", "Level 1, since a stock level must hold at least one unit", "A refusal, since a mean below 1 is too small to model", "Level 0, since the mean rounds down to no demand"]'::jsonb, 0, 'The reason reads: level 0: P(X <= 0) = 0.951229 is at or above 0.9 (Poisson mean 0.05). The chance of no demand at all over the protection period already meets the target, so no stock is needed. The engine refuses no small mean, and it rounds no mean.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 12, 'Periodic review on a Poisson item: 1.5 a period, lead time 2, review period 1, fill rate 0.95 with an order of 1.5. What level and mean come back?', '["Level 7 on a Poisson mean of 3, from the lead time alone", "Level 8 on a Poisson mean of 3, since a review period adds nothing to a Poisson mean", "Level 8 on a Poisson mean of 4.5", "Level 7 on a Poisson mean of 4.5"]'::jsonb, 2, 'The reason reads: level 8: expected units short 0.067581 is at or below 1.5 x (1 - 0.95) = 0.075; at 7 it is 0.154167 (Poisson mean 4.5). The mean is the demand rate times the lead time plus the review period, 1.5 times 3. Level 7 leaves 0.154167 short, above the allowance.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 13, 'At 5 a period the Poisson view is given a lead time of 100.5. How does the engine answer?', '["A level computed as usual, with a note that the normal would fit better", "A level from the normal safety stock, to which the engine hands the call on by itself", "A refusal naming demandRate, which must be at most 1 for a slow mover", "A refusal: leadTime must be at most 100 so that the mean demand demandRate x leadTime is at most 500"]'::jsonb, 3, 'The engine''s words: leadTime must be at most 100 so that the mean demand demandRate x leadTime is at most 500; above that the normal safetyStock serves; got 100.5. MAX_POISSON_MEAN is 500. The engine points to the normal safety stock and hands nothing on itself, and it caps the mean, with no cap of its own on the rate.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 14, 'MIL-HDBK-338B (1 October 1998), example 5.3.8.1, asks the chance of two lamp failures or fewer in 500 hours at 0.001 failures an hour. What does the engine return?', '["A Poisson mean of 0.500000 and a cumulative probability of 0.986 exactly, the handbook''s figure", "A Poisson mean of 0.500000 and a cumulative probability of 0.985612", "A Poisson mean of 2.000000, and 0.676676", "A Poisson mean of 0.5 and a cumulative probability of 0.952577"]'::jsonb, 1, 'A failure rate of 0.001 an hour over 500 hours is a Poisson mean of 0.500000, and the chance of two failures or fewer is 0.985612 (engine); the handbook prints 0.986. The engine prints its own figure at six decimals beside the print. 0.676676 is the level 2 cumulative of the PSV kits at a mean of 2.000000, and 0.952577 the level 2 cumulative of the lecture 13 table at a mean of 0.8.'),
  ('materials', 'intermediate', 'module', 'm06-poisson-demand-for-slow-movers', 15, 'A Poisson call on the pressure safety valve repair kits carries a key lambda_ for the demand rate. What comes back?', '["A level on a mean of 2.000000, with lambda_ read as the demand rate", "A level computed from the other inputs, with lambda_ dropped silently", "A refusal naming lambda_ and listing the accepted keys at the top level", "demandRate must be a finite number above 0; got undefined"]'::jsonb, 2, 'The engine''s words: lambda_ is not an accepted key; the accepted keys at the top level are demandRate, leadTime, reviewPeriod, serviceMeasure, serviceLevel, orderQuantity. Every function checks its accepted keys before it reads an input, so the unknown key is refused first, ahead of the missing demand rate, and nothing is dropped silently.'),
  ('materials', 'intermediate', 'final', null, 1, 'Which three figures make up the bound that every fill-rate reason sets on G(k)?', '["The safety factor and sigma alone, since G is read off k", "The order quantity Q, one less the fill rate, and the sigma", "The cycle service level and the demand over the protection period", "The order quantity and the lead time only"]'::jsonb, 1, 'Each fill-rate reason prints the target in the same form: 12 x (1 - 0.98) / 3.029476 = 0.079222 on the choke beans and 228 x (1 - 0.95) / 258.088834 = 0.044171 on the slide 24 data. The safety factor is what the target sets, found by bisection, and the cycle service level is the other measure.'),
  ('materials', 'intermediate', 'final', null, 2, 'At the incremental order of 1789.000000 on the lecture 8 schedule, what effective unit price does the engine report?', '["40, the price of the band the order lands in, applied to every unit", "44.192286, between the band prices of 45 and 40", "45, the price of band 1", "50, the band 0 price paid on the first units, applied to the whole lot"]'::jsonb, 1, 'Under an incremental schedule each unit is priced by its own band, so the lot cost is F2 plus 40 times Q, with F2 7500.000000. Spread over 1789 units that is an effective unit price of 44.192286, which lecture 8 slides 13 to 15 print as 44.19. A single band price for the whole lot is the all-units reading.'),
  ('materials', 'intermediate', 'final', null, 3, 'With no discount at all, slide 9 of lecture 8 costs one location: 2000 a year, 500 an order, a holding rate of 0.25 on a price of 50. What yearly ordering and holding costs come back at the EOQ?', '["2500.000000 of ordering and 5000.000000 of holding, a total of 105000.000000", "5000.000000 each, at an EOQ of 400.000000", "2500.000000 each, a relevant cost of 5000.000000 at an EOQ of 400.000000", "1000.000000 each, at an EOQ of 1000.000000"]'::jsonb, 2, 'The slide prints an order size of 400, an order cost of 2,500, a holding cost of 2,500 and a total of 5,000; the engine returns an EOQ of 400.000000, ordering cost 2500.000000, holding cost 2500.000000 and relevant cost 5000.000000. At the EOQ the two costs are equal. 105000.000000 adds the purchase cost at 50 a unit.'),
  ('materials', 'intermediate', 'final', null, 4, 'At level 3 of the Poisson table on a weekly mean of 0.8 (Caplice, lecture 13 slides 11 and 12), what cumulative probability does the engine print?', '["0.998589", "0.952577", "0.038343", "0.990920"]'::jsonb, 3, 'At level 3 the cumulative figure is 0.990920, which the slide prints to one decimal of a percent. The other figures are the level 4 cumulative 0.998589, the level 2 cumulative 0.952577 and the level 3 probability 0.038343.'),
  ('materials', 'intermediate', 'final', null, 5, 'A golden input breaks a tie by dropping the second band''s price to three quarters of band 0. What does the engine order now?', '["The break of 200, costing 175 a year", "100 in band 0, at a total cost of 200 a year, as the tie reading still takes the smaller lot", "200 in band 1 at 200 a year, the tie unchanged", "175 units, the cost read as a quantity"]'::jsonb, 0, 'The reason reads: order 200 at a total cost of 175 a year (band 1), the lowest of 2 candidates. With the price cut the break costs less than band 0''s EOQ of 100 at 200 a year, so there is no tie left for the smaller-quantity reading to settle.'),
  ('materials', 'intermediate', 'final', null, 6, 'Someone types a holding rate of 0 into a quantity discount call, as if stock cost nothing to keep. How does the engine answer?', '["A refusal on holdingRate, which must be above 0", "breaks must be an array of at least 1 price band { minQuantity, unitPrice }", "An order at the largest break, holding costing nothing", "breaks[1].unitPrice must be below the band before it (50); got 50"]'::jsonb, 0, 'A holding rate of 0 would make every lot free to hold, and the engine refuses it by name: holdingRate must be a finite number above 0; got 0. The breaks message answers an empty schedule, and the unitPrice message a band whose price does not fall. The engine orders nothing on a holding rate it refuses.'),
  ('materials', 'intermediate', 'final', null, 7, 'A price band is typed with the key price where the engine expects unitPrice. What comes back?', '["breaks[0].unitPrice must be a finite number above 0; got undefined", "The order as usual, with the misspelt key price read as the band''s unit price after all", "The order as usual, with the band priced at 0 for want of a unit price", "breaks[0].price is not an accepted key; the accepted keys of breaks[0] are minQuantity, unitPrice"]'::jsonb, 3, 'An input key a function does not read is refused at whatever level it sits, a price band included, with the path to the key and the full list of accepted keys. A misspelt key is refused; it is never dropped silently. The unknown key is refused before any missing input is read.'),
  ('materials', 'intermediate', 'final', null, 8, 'How many price bands will one quantity discount call accept, and what does a schedule of twenty-one bands return?', '["Any number, since every band a supplier offers must be costed", "At most 10, the cap on slow-moving bands, applied to prices too", "At most 20, with the bands past the cap dropped from the call", "At most 20; the engine replies: breaks has 21 entries; the cap is 20"]'::jsonb, 3, 'One quantity discount call accepts at most 20 price bands, and a schedule of twenty-one is refused whole: breaks has 21 entries; the cap is 20. The cap of 10 belongs to the slow-moving bands. A cap refuses the call and drops no band silently.'),
  ('materials', 'intermediate', 'final', null, 9, 'Under all-units on the casing, band 1''s EOQ is 77.459667. Under incremental, the same band''s EOQ is 105.559733. Why do they differ?', '["Incremental prices band 1 at 1450, the band 0 price", "All-units rounds the EOQ to the nearest joint first", "Incremental adds the band''s fixed cost 3000.000000 to the order cost", "Incremental uses a holding rate on the band 0 price, so holding costs more and the lot is larger"]'::jsonb, 2, 'The incremental basis gives EOQi = sqrt(2 D (A + Fi) / (r vi)): band 1 carries F1 3000.000000 on top of the order cost of 3500, at its own price of 1400, which lifts its EOQ to 105.559733. All-units band 1 uses the order cost alone at 1400 and gets 77.459667. Rounding acts after the EOQ.'),
  ('materials', 'intermediate', 'final', null, 10, 'Which of the choke bean set''s two sources of variation contributes more to its sigma, according to the stated probes?', '["The lead-time spread: 2.529822 alone against 1.666650 from demand", "Neither: each source contributes the full sigma of 3.029476 when taken on its own", "The demand spread: 2.529822 alone against 1.666650 from the lead-time spread", "The lead-time spread, since the lead time of 2.5 months is longer than a month"]'::jsonb, 2, 'With the lead-time spread set to 0, sigma is 2.529822, all of it from demand; with the demand spread set to 0, sigma is 1.666650, all of it from the lead time. The two combine as squares into 3.029476. For this item demand variation is the larger part.'),
  ('materials', 'intermediate', 'final', null, 11, 'Steady use of 20 each period meets a 5-period lead time whose spread is the only uncertainty. Which demand over the lead time and held reorder point appear in the reason?', '["A demand of 100 and a reorder point held as 130", "A demand of 20 and a reorder point of 50", "A demand of 100 and a reorder point held as 100, with no safety stock", "A demand of 30 and a reorder point held as 130"]'::jsonb, 0, 'The reason reads: safety stock 30 over a demand of 100 with sigma 30 gives the reorder point s 130, held as 130 (up to a multiple of 5). The lead-time spread sets a sigma of 30.000000 even with steady demand, so the safety stock is above 0. 30 is the safety stock, and 100 the demand over the five periods.'),
  ('materials', 'intermediate', 'final', null, 12, 'A copy of the choke bean call removes the rounding rule altogether. What message comes back?', '["A reorder point held as 13.316294, the exact level, as a missing rule means no rounding", "A reorder point held as 14.000000, the rule up to a multiple of 1 taken from the fixture", "rounding must be a stated rounding rule { rule: ''none'' } or { rule: ''up'' | ''down'' | ''nearest'', multiple }", "safetyFactorRounding must be { rule: ''none'' } or { rule: ''nearest'', decimals } (a table read to that many decimals)"]'::jsonb, 2, 'The rounding rule is a stated input with no default, and a call without one is refused by name. The start "The choke bean set, cycle service level" with its rounding removed returns the message in the key. No rounding is a rule that must be stated as { rule: ''none'' }. The safetyFactorRounding message is about the table reading of k.'),
  ('materials', 'intermediate', 'final', null, 13, 'The choke bean target moves from 0.9 to 0.975 as a cycle service level. What happens to k and to the held reorder point?', '["k rises from 1.281552 to 1.959964, and the held level from 13.000000 to 15.000000", "k rises from 1.281552 to 1.959964 and the held level stays at 14.000000", "k stays at 1.644854, and only the held level moves", "k falls, since a higher level needs less safety stock"]'::jsonb, 0, 'The stated probes give k 1.281552 and a reorder point of 12.215679, held as 13.000000, at 0.9; and k 1.959964 and 14.270913, held as 15.000000, at 0.975. The factor is the inverse normal of the level, so it rises with the level, and so does the held level.'),
  ('materials', 'intermediate', 'final', null, 14, 'At a cycle service level of 0.9, CHK-BEAN''s reorder point 12.215679 is held as 13.000000. What achieved cycle service does the engine report?', '["0.9", "0.810643", "0.938274", "0.969295"]'::jsonb, 2, 'Rounding up raises the service, and the engine reports the service a held level achieves beside the target: at 0.9 the held level 13.000000 achieves 0.938274. 0.810643 is the achieved figure at 0.8 and 0.969295 at 0.95.'),
  ('materials', 'intermediate', 'final', null, 15, 'The 0.90 row of the cycle service column on Caplice, lecture 11 slide 24, is reproduced when k comes off a two-decimal table and the level is rounded to a whole unit. Which reorder point results?', '["830.000000, on a table factor of 1.28", "1101.000000, on a table factor of 2.33", "717.000000, on a table factor of 0.84", "923.000000, on a table factor of 1.64"]'::jsonb, 0, 'Read to two decimals, k is 1.28 and the level is held as 830.000000; less the demand over the lead time of 500.000000, that is the 330 the slide prints. The exact safety stock is 330.754149. 717.000000 is the held level at 0.80, 923.000000 the one at 0.95 and 1101.000000 the one at 0.99.'),
  ('materials', 'intermediate', 'final', null, 16, 'Over the two-week lead time of the lecture 11 check, what demand and sigma does the engine compute?', '["A demand of 250.000000 and a sigma of 182.496365, the weekly figures", "A demand of 500.000000 and a sigma of 258.088834, over the two weeks", "A demand of 13,000 and a sigma of 1,316, the annual figures", "A demand of 500.000000 and a sigma of 182.496365, the weekly spread unchanged"]'::jsonb, 1, 'Over the two weeks the demand is 500.000000 with a sigma of 258.088834 (engine): twice the weekly demand, and the weekly spread grown with the square root of the period. The annual figures are the slides'' statement, which the golden inputs scale to a week first.'),
  ('materials', 'intermediate', 'final', null, 17, 'A choke bean call states the safety factor reading as nearest with no decimals given. What does the engine return?', '["A reorder point with k read to 0 decimals, the smallest reading", "The call is refused: the decimals must be a whole number from 0 to 6, and none was given", "A reorder point with the exact k, since no decimals means no table", "safetyFactorRounding.decimals must be left out when the rule is ''none''"]'::jsonb, 1, 'A table reading needs its number of decimals, and the start "The choke bean set, cycle service level" returns, in its own words: safetyFactorRounding.decimals must be a whole number from 0 to 6; got undefined. The engine fills in no reading of its own. The message about leaving decimals out answers the rule none with decimals beside it.'),
  ('materials', 'intermediate', 'final', null, 18, 'Bisecting for k at a fill rate of 0.90 on the weekly data, which safety stock does the engine reach, beside the 252 printed on Caplice, lecture 11 slide 24?', '["252, as printed, with k read from a table", "330.754149, with k 1.281552", "250.102945, with k 0.969058", "147.444755, with k 0.571295"]'::jsonb, 2, 'Solving for k by bisection at a fill rate of 0.90 gives 0.969058 and a safety stock of 250.102945, 1.897055 below the print, within the 2 units three rows agree to. 330.754149 is the exact cycle service figure at 0.90, and 147.444755 the fill-rate figure at 0.80.'),
  ('materials', 'intermediate', 'final', null, 19, 'How far does each printed fill-rate safety stock on Caplice, lecture 11 slide 24, sit from the engine''s figure?', '["0.650714, 8.820396, 1.897055 and 0.555245, from 0.99 down to 0.80", "Within 2 units in every row, so the column holds no slip at all", "8.820396 in every row, a constant offset from a different k table", "Exactly 0 in every row once k is read from a table to two decimals"]'::jsonb, 0, 'The printed less the engine is 0.650714 at 0.99, 8.820396 at 0.95, 1.897055 at 0.90 and 0.555245 at 0.80. Three rows agree to within 2 units; the 0.95 row is a slip. No reading of k closes it, since the rule at 0.95 meets its target exactly at 339.179604.'),
  ('materials', 'intermediate', 'final', null, 20, 'A golden input puts the band 0 EOQ beyond the only break, so the schedule offers one candidate. What reason does the engine print?', '["order 400 at a total cost of 105000 a year (band 0), the lowest of 1 candidate", "order 4600 at a total cost of 483717.83 a year (band 1), the lowest of 1 candidate", "order 4600 at a total cost of 483717.83 a year (band 0), the lowest of 2 candidates", "band 0 gives no candidate, so the whole schedule is refused as offering no order at all"]'::jsonb, 1, 'On that schedule the reason reads: order 4600 at a total cost of 483717.83 a year (band 1), the lowest of 1 candidate. Band 0''s EOQ lies at or above the break, so band 0 offers nothing and band 1 offers the only candidate. The reason ordering 400 at 105000 belongs to a schedule with one band.'),
  ('materials', 'intermediate', 'final', null, 21, 'An order quantity of 0 goes into the fill-rate choke bean case. How is it answered?', '["Refused by name: the order quantity must be above 0", "A fill rate of 0.98 met at any k, as no units are brought", "orderQuantity is required for a fill rate (units short are measured against the quantity each cycle brings)", "A safety factor of 1.026327, since 0 is read as the fixture''s 12"]'::jsonb, 0, 'An order quantity must be above 0, and the engine refuses 0 by name: orderQuantity must be a finite number above 0; got 0. The message saying an order quantity is required answers one that is missing altogether. The engine never swaps in a figure of its own.'),
  ('materials', 'intermediate', 'final', null, 22, 'Moving the choke bean set to monthly review adds a month to its protection period. Which part of sigma grows, and which stays?', '["The lead-time term grows, since the review period carries a spread of its own", "Both terms grow in proportion to the protection period", "Neither grows, since sigma is set by the lead time alone", "The demand term grows with P; the lead-time term d^2 sd_L^2 stays"]'::jsonb, 3, 'The rule multiplies the demand variance by P = leadTime + reviewPeriod, so a longer P widens that term; the lead-time variance d^2 sd_L^2 carries no review period. On the choke beans sigma goes from 3.029476 to 3.426036.'),
  ('materials', 'intermediate', 'final', null, 23, 'A fill rate of 0.95 on an order of 2000 sets a bound on G(k) that Caplice, lecture 12 slides 5 and 6, round to 0.1733. What bound does the reason carry?', '["0.044171, from 228 x (1 - 0.95) / 258.088834", "0.173279, from 2500 x (1 - 0.95) / 577.104177", "0.58, the safety factor as the table reads it", "0.173279, from 2000 x (1 - 0.95) / 577.104177"]'::jsonb, 3, 'The reason reads: a fill rate of 0.95 needs G(k) at or below 2000 x (1 - 0.95) / 577.104177 = 0.173279. The order quantity is 2000, the demand over one review period; 2500 is the demand over the whole protection period. 0.044171 is the lecture 11 target at 0.95.'),
  ('materials', 'intermediate', 'final', null, 24, 'Caplice, lecture 12 slides 5 and 6, review every 8 weeks on a lead time of 2 weeks. Over what protection period, and on what demand over it, does the engine work?', '["8 weeks and 2000, the review period alone", "10 weeks and 2500.000000", "2 weeks and 500.000000, the lead time only", "10 weeks and 2000"]'::jsonb, 1, 'Eight weeks of review and two of lead time make 10 weeks, and at 250 a week that is 2500.000000. The figure 2000 covers the review period only, and 500.000000 the lead time only.'),
  ('materials', 'intermediate', 'final', null, 25, 'On the Caplice lecture 8 incremental schedule, band 0 prices every unit at 50 below 500. What candidate does band 0 offer, and at what yearly total?', '["500.000000 at 103062.500000, the break of band 1", "No candidate, since band 1 is cheaper", "1032.795559, carried down from band 1", "400.000000 at 105000.000000, its own EOQ inside the band"]'::jsonb, 3, 'Band 0''s EOQ of 400.000000 lies inside the band from 0 to below 500, so it is the band''s candidate, costed at 105000.000000 a year. It loses to band 2''s 1789.000000 at 98826.043879. 500.000000 at 103062.500000 answers the two-band all-units schedule of slide 12, and 1032.795559 is band 1''s EOQ, which offers nothing.'),
  ('materials', 'intermediate', 'final', null, 26, 'On the PSV kits at a mean of 2.000000, the probabilities of exactly one kit and exactly two kits are equal. What figure does the engine print for each?', '["0.135335", "0.270671", "0.406006", "0.180447"]'::jsonb, 1, 'The recursion p(x) = p(x - 1) m / x multiplies by 2 over 2 from level 1 to level 2, so both are 0.270671. 0.135335 is the chance of no demand, 0.406006 the cumulative to level 1, and 0.180447 the probability at level 3.'),
  ('materials', 'intermediate', 'final', null, 27, 'What expected units short beyond level 4 does the engine print for the PSV kits?', '["0.090224", "0.022488", "0.218018", "0.075141"]'::jsonb, 3, 'The loss column reads 2.000000, 1.135335, 0.541341, 0.218018, 0.075141 and 0.022488 for levels 0 to 5, so L(4) is 0.075141. 0.090224 is the probability of exactly four kits, 0.022488 the loss at level 5 and 0.218018 the loss at level 3.'),
  ('materials', 'intermediate', 'final', null, 28, 'How likely is a week with no demand at all for the weekly slow mover of Caplice, lecture 13 slides 11 and 12, by the engine and by the print?', '["0.359463 against the printed 35.9%", "0.449329 against the printed 44.9%", "0.449329 against the printed 45%", "0.808792 against the printed 80.9%"]'::jsonb, 1, 'The probability at level 0 is 0.449329, which the slide prints as 44.9%. 0.359463 is level 1''s probability, and 0.808792 the cumulative to level 1. Every level below 4 agrees with the slide at the precision it prints.'),
  ('materials', 'intermediate', 'final', null, 29, 'A Poisson call states a demand rate of 3 a period and a lead time of 170. What does the engine return?', '["A level on a mean above 500, computed as usual", "A refusal naming the largest lead time accepted, 166.666666, rounded down at the sixth decimal", "A refusal naming demandRate, which must be at most 3", "A refusal naming the largest lead time accepted, rounded to the nearest whole period"]'::jsonb, 1, 'The engine''s words: leadTime must be at most 166.666666 (rounded down at the sixth decimal so that it is accepted) so that the mean demand demandRate x leadTime is at most 500; above that the normal safetyStock serves; got 170. A largest accepted value is rounded toward the accepted side, so typing it back is accepted.'),
  ('materials', 'intermediate', 'final', null, 30, 'Typing 1.2 as the target of a slow-mover call: what message comes back?', '["serviceLevel must be a number strictly between 0 and 1; got 1.2", "A level at the cycle service level of 1, the largest accepted", "serviceMeasure must be ''cycle-service'' (probability of no stockout over the protection period) or ''fill-rate'' (fraction of demand met from stock)", "The level at which the cumulative probability reaches 1"]'::jsonb, 0, 'A service level is a probability strictly between 0 and 1, in the Poisson view as in the normal one, and 1.2 is refused by name. The engine caps nothing silently, and no Poisson level reaches a cumulative probability of 1. The serviceMeasure message answers a missing or unknown measure.'),
  ('materials', 'intermediate', 'final', null, 31, 'At a fill rate of 0.95 with k read to two decimals, how much safety stock does the engine report on the periodic review of Caplice, lecture 12 slides 5 and 6?', '["334.720422, from k read as 0.58 on a sigma of 577.104177", "2834.720422, the order-up-to level before it is held as 2835.000000", "2500.000000, the demand over the ten-week protection period", "577.104177, the sigma over the protection period at a factor of 1"]'::jsonb, 0, 'The engine''s reason reads: safety stock 334.720422 over a demand of 2500 with sigma 577.104177 gives the order-up-to level S 2834.720422. The exact factor 0.583373 is read as 0.58, and 0.58 times the sigma is the safety stock. 2834.720422 is the level itself, 2500.000000 the demand the level covers and 577.104177 the sigma.'),
  ('materials', 'intermediate', 'final', null, 32, 'On the lecture 11 weekly data at 0.95, the cycle service measure with exact k and the fill-rate measure give different safety stocks. Which pair does the engine return?', '["339.179604 for cycle service and 424.518354 for the fill rate", "423.000000 for both, since the level is the same", "424.518354 for cycle service and 339.179604 for the fill rate", "424.518354 for cycle service and 348 for the fill rate"]'::jsonb, 2, 'With the exact k the cycle service safety stock at 0.95 is 424.518354; the fill-rate rule at 0.95 with an order quantity of 228 gives 339.179604. 348 is the slip the slide prints for the fill rate, and 423 is the cycle service figure under the table reading.'),
  ('materials', 'intermediate', 'final', null, 33, 'On certain demand, a demand of 10 a period with no spread over a lead time of 3, how do the two service measures fare?', '["Both are refused, since certain demand leaves nothing to protect", "Both are accepted, each with a safety stock of 0.000000", "A cycle service target is accepted; a fill rate is refused", "A fill rate is accepted and a cycle service target is refused"]'::jsonb, 2, 'Sigma is 0.000000 here, so a cycle service target is met by the reorder point 30.000000 with no safety stock. The fill-rate search has nothing to solve, and the engine says so by name, naming demandSd as its field.'),
  ('materials', 'intermediate', 'final', null, 34, 'The course meets two printed slips, one on lecture 11 slide 24 and one on lecture 13 slide 12. What does it do with both?', '["Replaces each print with the engine''s figure and drops the print", "Keeps each print beside the rule''s own figure, and keeps the rule", "Tunes the engine until it reproduces 348 and 0.009", "Treats both as rounding noise within 2 units"]'::jsonb, 1, 'The course keeps each printed figure beside the rule''s own figure and teaches the difference, and it does not change the rule to match a print: 339.179604 beside 348, and 0.001619 beside 0.009. The 0.95 row misses by 8.820396 and the level 4 loss is not the recursion''s figure at any precision the slide uses.'),
  ('materials', 'intermediate', 'final', null, 35, 'What mean does each engine view take over the protection period when a review period is stated, in the normal view and the Poisson view?', '["The normal view adds the review period; the Poisson view uses the lead time alone", "The Poisson view adds the review period; the normal view uses the lead time alone", "Both take the demand a period times leadTime + reviewPeriod", "Neither adds the review period, which only sets how often stock is counted"]'::jsonb, 2, 'The normal rule has P = leadTime + reviewPeriod and a level of d P + k sigma; the Poisson rule reads X ~ Poisson(demandRate x (leadTime + reviewPeriod)). So a review period lengthens the protection period in both: on the Poisson case with a review period of 1 the mean is 4.5, and on the choke beans the demand over P becomes 11.666550.'),
  ('materials', 'intermediate', 'final', null, 36, 'A stated Poisson call at 2 a period, with a review period stated, asks for a lead time of 240. Which ceiling does the refusal quote?', '["250, the lead time that alone gives a mean of 500", "240, the stated lead time, since the review period is fixed", "229.5, with the review period left out of the mean", "229.5, as the review period counts toward the mean"]'::jsonb, 3, 'The refusal quotes 229.5 and gives its reason: so that the mean demand demandRate x (leadTime + reviewPeriod) is at most 500. The stated review period counts toward the mean, which is why the ceiling is lower than the lead time alone would allow.'),
  ('materials', 'intermediate', 'final', null, 37, 'Which calculator panel of this course carries the Professional practicals, and which engine functions does it call?', '["The stock calculator: quantityDiscount, safetyStock, poissonStock", "The register calculator: criticality, abcClassification, eoq, slowMoving", "The spares calculator: insuranceSpares, poissonStock, leadTimeRisk", "The Materials & Spares Planner alone, which needs a Suite seat"]'::jsonb, 0, 'The stock calculator (materials-stock-calculator) is the Professional panel and calls quantityDiscount, safetyStock and poissonStock. It calls the same vendored engine as the Materials & Spares Planner, so every exercise can be done without a Suite seat. The register calculator is the Associate panel and the spares calculator the Expert one.'),
  ('materials', 'intermediate', 'final', null, 38, 'Where does every graded number in this course come from?', '["A figure printed in the Caplice lectures, checked against the engine", "The median of a seeded Monte Carlo run of the engine", "An average of the engine''s figure and the printed one", "A return value of the engine on inputs written down in advance"]'::jsonb, 3, 'Every graded number is a return value of the engine on fixed inputs, so the same inputs give the same number on any machine and there is exactly one right answer. No graded figure comes from the Monte Carlo, and a printed figure can carry a slip.'),
  ('materials', 'intermediate', 'final', null, 39, 'A call carries an unknown key and also leaves out a required input. Which does the engine refuse first?', '["The missing input, since required inputs are checked first", "The unknown key, since keys are checked before any input is read", "Both at once, in one message listing each problem", "Neither: the unknown key is dropped and the default input used"]'::jsonb, 1, 'Every function checks its accepted keys before it reads an input, so a box with an unknown key and a missing required input is refused on the unknown key first. The engine holds no default input, and each refusal names one field.'),
  ('materials', 'intermediate', 'final', null, 40, 'In this course''s vocabulary, what does the term safety stock name?', '["k times sigma over the protection period", "The whole reorder point, the level at which an order goes out", "The order-up-to level that periodic review tops up to", "Any stock held back just in case something fails"]'::jsonb, 0, 'The vocabulary rule: safety stock is k times sigma over the protection period; the reorder point and the order-up-to level are named as such. On the choke beans the safety stock is 4.983044 and the reorder point 13.316294, two different figures.'),
  ('materials', 'intermediate', 'final', null, 41, 'A slow mover''s Poisson level comes back as a whole number. What does the engine report as its safety stock?', '["The level itself, as every kit on the shelf is safety stock", "k times sigma, with sigma the square root of the mean", "The level less one, the kit in use", "The level less the Poisson mean over the protection period"]'::jsonb, 3, 'The PSV kits at level 5 on a mean of 2.000000 give a safety stock of 3.000000, the level less the mean. The Poisson view computes no k and no sigma; it reads the level off the table. On the mean of 0.05 at level 0 the safety stock is below zero.'),
  ('materials', 'intermediate', 'final', null, 42, 'A result comes back with a reason saying some demand goes short, or that a target was met only at a high level. Is that a refusal?', '["Yes, since any shortage in a draw is refused by name", "Yes, whenever the reason it prints names a limit", "No: a result returned with a reason is a result", "Only when the achieved service falls below the target"]'::jsonb, 2, 'A refusal is an object with error and field, and the message starts with the field it refuses. A result returned with a reason (an item below a class minimum, a stock of spares at the search limit, a stockout in some draws) is a result. It is no refusal.');
